async ({ shell: { execFile } }) => {
  const i = await execFile("npm", ["ci"], { timeoutMs: 200000, maxLines: 10, truncate: "tail" });
  if (i.code !== 0) return { install: i.stdout + i.stderr };
  const chk = await execFile("npm", ["run", "check"], { timeoutMs: 250000, maxLines: 25, truncate: "tail" });
  if (chk.code !== 0) return { failed: chk.stdout + chk.stderr };
  const st = await execFile("git", ["status", "--short"]);
  return { ok: chk.stdout.slice(-600), st: st.stdout };
}
